//! The NCEP/NCAR Reanalysis 1's monthly 2 m air temperature over 1991–2020, reduced to the sea
//! level over land at the reference Earth's lapse rate, on Earth's land boxes (R09.T13.l, R09.T13.m):
//! the observed side of the geographic model's comparison with observed climatologies
//! ([`climatology`](super::climatology)), its boxes those of [`gpcp_boxes`](super::gpcp_boxes), in
//! the same order. Test data, not shipped (`NOTICE`, "Test data (not shipped)"). NOAA PSL's data
//! are in the public domain. The dataset's citation: E. Kalnay et al. 1996, "The NCEP/NCAR 40-Year
//! Reanalysis Project", Bull. Amer. Meteor. Soc. 77, 437–471.
//!
//! # The inputs
//!
//! NOAA PSL's files as the Internet Archive's 2022 snapshot of `downloads.psl.noaa.gov` holds them
//! (`web.archive.org/web/2022id_/https://downloads.psl.noaa.gov/Datasets/…`, the original bytes):
//!
//! - `ncep.reanalysis.derived/surface_gauss/air.2m.mon.ltm.1991-2020.nc`, `air`, the long-term
//!   monthly means on the T62 Gaussian grid (94 × 192), K: 964,084 bytes, SHA-256
//!   `c86a3c575010ca2c9414b24022361c43be6966dcdc62c821c1918e9c44ca9be9`;
//! - `ncep.reanalysis/surface_gauss/land.sfc.gauss.nc`, `land`, the land mask on the same grid:
//!   SHA-256 `7da97a6d508a499302002891bb11e7c284d99019698cb89de1b5f5da37df3ca3`;
//! - `ncep.reanalysis/surface/hgt.sfc.nc`, `hgt`, the surface height on the 2.5° grid (73 × 144),
//!   m: SHA-256 `ca400fd56fc2c2f45352a7d80aefff7b349e7093ead14d4e788eb0d122835de3`.
//!
//! They are the data [`ncep_air`](super::ncep_air) reduces: reduced and banded as it documents,
//! they reproduce its `SEA_LEVEL_AIR_K` to 0.000 K in all 12 × 72 values.
//!
//! # The method
//!
//! - Each point's temperature, plus Γ max(0, z) where the land mask exceeds 0.5, with Γ
//!   [`REDUCTION_LAPSE_RATE_K_PER_M`](super::ncep_air::REDUCTION_LAPSE_RATE_K_PER_M), 5.829 K km⁻¹:
//!   [`ncep_air`](super::ncep_air)'s reduction, z the 2.5° grid's height at the row nearest the
//!   point's latitude (the first of ties) and the column round(λ ÷ 2.5°) mod 144.
//! - A box's value: the overlap-weighted mean of the Gaussian cells over it, each row bounded in
//!   sine latitude by the cumulative Gauss–Legendre weights (which sum to 2) and each column 1.875°
//!   wide about its point.
//! - Printed in hundredths of a kelvin.
//!
//! Against the σ = 0.995 table it replaced (NOAA ARL's archive of the reanalysis, R09.T13.l's), over
//! the land boxes by solid angle: −0.60 to −0.98 K by month (RMS 1.45–1.64 K), −0.81 K annually (RMS
//! 1.41 K), 66% of the land boxes' area within ±1 K annually and 89% within ±2 K.
//!
//! The script, research-r09-climate's `ncep_2m_boxes.py`, is not in the repository.

/// Each land box's band (from the south pole) and column (of 5° from −180° of longitude), and its
/// monthly mean 2 m air temperature reduced to the sea level over land, hundredths of a kelvin,
/// January first ([module documentation](self)): the boxes of
/// [`gpcp_boxes`](super::gpcp_boxes)'s table, in its order.
